"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["3437"],{44544(e){e.exports=JSON.parse('{"id":"FIN-1184","slug":"impact-investing","term":"Impact Investing","also_known_as":[],"difficulty":"Advanced","definition":"Impact investing is investing with the intention of generating measurable positive social or environmental outcomes alongside a financial return.","explanation":["Impact investors seek to make a difference through their investments, such as providing affordable housing, expanding renewable energy, improving healthcare access or supporting small businesses in underserved communities.","Two features distinguish impact investing from broader approaches. First, the intention to create positive impact is central, not a side effect. Second, impact is measured and reported, using specific indicators such as homes built, emissions avoided or people served.","For example, an impact fund might lend to small businesses in low-income areas, aiming to earn a modest return while tracking jobs created and incomes improved.","Expected financial returns vary. Some impact investors seek market-rate returns, while others accept lower returns to achieve greater impact. Impact investing is common in private markets, such as private equity, private debt and venture capital, but also includes certain bonds, such as green and social bonds. Measuring and verifying impact consistently remains a challenge."],"note":"","total":1725,"prev":{"slug":"immediate-annuity","term":"Immediate Annuity"},"next":{"slug":"impairment","term":"Impairment"}}')}}]);